(()=>{const toggle=document.getElementById('menu-toggle'),nav=document.getElementById('main-nav');if(!toggle||!nav)return;toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}));})();
(()=>{const banner=document.getElementById('audience-banner'),button=document.getElementById('dismiss-banner');if(!banner||!button)return;try{banner.hidden=sessionStorage.getItem('mm-banner-dismissed')==='1'}catch{}button.addEventListener('click',()=>{banner.hidden=true;try{sessionStorage.setItem('mm-banner-dismissed','1')}catch{}})})();